#include<bits/stdc++.h>
#define int long long
#define endl "\n"
using namespace std;
const int N=2e6+10;
int _c,t;
int n,d;
int x[N],tag[N];
int r[N];
int f[N],g[N],c[N];
vector<int> l[N];
void solve()
{
	cin>>n>>d;
	for(int i=1;i<=n;i++)
		cin>>x[i];
	for(int i=1;i<=n;i++)
	{
		l[i].clear();
		f[i]=1;
		g[i]=1;
		c[i]=0;
		tag[i]=0;
	}
	for(int i=1;i<=n;i++)
	{
		r[i]=upper_bound(x+i,x+1+n,x[i]+d)-x-1;
		if(i!=r[i])l[r[i]].push_back(i);
//		cout<<r[i]<<" ";
	}
//	cout<<endl;
	for(int i=1;i<=n;i++)
	{
		if(!l[i].empty())
		{
			f[i]+=l[i].size()-1;
			f[i]+=f[l[i][0]];
		}
		if(l[i].empty())
			c[i]=c[i-1]+1;
	}
	for(int i=n;i>=1;i--)
	{
		if(!l[i].empty())
		{
			int j=l[i][0];
			g[j]+=g[i]+c[i-1];
		}
	}
//	for(int i=1;i<=n;i++)
//		cout<<f[i]<<" ";
//	cout<<endl;
//	for(int i=1;i<=n;i++)
//		cout<<g[i]<<" ";
//	cout<<endl;
	int ans=0;
	for(int i=1;i<=n;i++)
	{
		int x=r[i],y=x-1,z=x-2;
		if(z<i)continue;
		int zz=r[z],yy=r[y];
		int xx=r[x];
//		printf("i:%lld x:%lld xx:%lld y:%lld yy:%lld z:%lld zz:%lld\n",i,x,xx,y,yy,z,zz);
		if(zz==yy)continue;
		if(r[i-1]>z)f[i]=1;
		if(xx==yy)
			ans+=f[i]*g[yy]+(yy-zz-1)*f[i];
		else ans+=f[i]*(yy-zz);
	}
	cout<<ans<<endl;
}
signed main(){
	// freopen("migrate.in", "r", stdin);
	// freopen("migrate.out", "w", stdout);
	ios::sync_with_stdio(false);
	cin.tie(0);
	cin>>_c>>t;
	while(t--)solve();
	return 0;
}
